// Verilator twin of gemmini_tb.prp (16x16 mesh), generated by gen_simtop.py: the same stimulus, the same fold,
// the same printed line. DUT: GemminiTPU itself; its packed-struct ports are packed and unpacked here as the
// flat-port wrapper GemminiSimTop does. Schedule: drive, eval at clock=0, posedge eval, read (as the 8x8 twin).
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#include "VGemminiTPU.h"
#include "verilated.h"

static inline uint64_t bits(uint64_t v, int lo, int n) { return (v >> lo) & ((n == 64) ? ~0ULL : ((1ULL << n) - 1)); }
template <typename W> static void wset(W& w, int lo, int n, uint64_t v) {
  for (int i = 0; i < n; ++i) {
    const int b = lo + i;
    const uint32_t m = 1u << (b % 32);
    if (i < 64 && ((v >> i) & 1)) w[b / 32] |= m; else w[b / 32] &= ~m;
  }
}
template <typename W> static uint64_t wget(const W& w, int lo, int n) {
  uint64_t v = 0;
  for (int i = 0; i < n; ++i) v |= (uint64_t)((w[(lo + i) / 32] >> ((lo + i) % 32)) & 1) << i;
  return v;
}

int main(int argc, char** argv) {
  uint64_t cycles = 1000;
  for (int i = 1; i < argc; ++i) {
    if (!std::strcmp(argv[i], "--cycles") && i + 1 < argc) cycles = std::strtoull(argv[++i], nullptr, 0);
    else { std::fprintf(stderr, "usage: %s [--cycles N]\n", argv[0]); return 2; }
  }
  Verilated::commandArgs(argc, argv);
  auto* t = new VGemminiTPU;
  uint64_t lfsr = 0x123456789abcdefULL;
  uint64_t sum  = 0;
  uint64_t obs  = 0;

  for (uint64_t cycle = 0; cycle < cycles; ++cycle) {
    t->clock = 0;
    t->reset = (cycle < 4);
    t->io_mesh_a_valid = bits(lfsr, 0, 1);
    wset(t->io_mesh_a_bits, 0, 64, bits(lfsr, 0, 64));
    wset(t->io_mesh_a_bits, 64, 64, bits(lfsr, 8, 56));
    t->io_mesh_b_valid = bits(lfsr, 1, 1);
    wset(t->io_mesh_b_bits, 0, 64, bits(lfsr, 1, 63));
    wset(t->io_mesh_b_bits, 64, 64, bits(lfsr, 9, 55));
    t->io_mesh_d_valid = bits(lfsr, 2, 1);
    wset(t->io_mesh_d_bits, 0, 64, bits(lfsr, 2, 62));
    wset(t->io_mesh_d_bits, 64, 64, bits(lfsr, 10, 54));
    t->io_mesh_req_valid = bits(lfsr, 3, 1);
    t->io_mesh_req_bits = (bits(lfsr, 20, 1) << 16) | (bits(lfsr, 21, 1) << 15) | (bits(lfsr, 22, 1) << 14) |
                          (bits(lfsr, 23, 5) << 9) | (bits(lfsr, 28, 1) << 8) | (bits(lfsr, 29, 1) << 7) |
                          (bits(lfsr, 30, 5) << 2) | bits(lfsr, 34, 2);
    t->io_acc_write_valid = bits(lfsr, 4, 1);
    wset(t->io_acc_write_bits, 577, 6, bits(lfsr, 35, 6));
    wset(t->io_acc_write_bits, 65, 64, bits(lfsr, 0, 64));
    wset(t->io_acc_write_bits, 129, 64, bits(lfsr, 1, 63));
    wset(t->io_acc_write_bits, 193, 64, bits(lfsr, 2, 62));
    wset(t->io_acc_write_bits, 257, 64, bits(lfsr, 3, 61));
    wset(t->io_acc_write_bits, 321, 64, bits(lfsr, 4, 60));
    wset(t->io_acc_write_bits, 385, 64, bits(lfsr, 5, 59));
    wset(t->io_acc_write_bits, 449, 64, bits(lfsr, 6, 58));
    wset(t->io_acc_write_bits, 513, 64, bits(lfsr, 7, 57));
    wset(t->io_acc_write_bits, 64, 1, bits(lfsr, 41, 1));
    wset(t->io_acc_write_bits, 0, 64, bits(lfsr, 0, 64));
    t->io_acc_read_req_valid = bits(lfsr, 5, 1);
    wset(t->io_acc_read_req_bits, 139, 32, bits(lfsr, 0, 32));
    wset(t->io_acc_read_req_bits, 133, 6, bits(lfsr, 44, 6));
    wset(t->io_acc_read_req_bits, 5, 128, 0);
    wset(t->io_acc_read_req_bits, 2, 3, bits(lfsr, 50, 3));
    wset(t->io_acc_read_req_bits, 1, 1, bits(lfsr, 53, 1));
    wset(t->io_acc_read_req_bits, 0, 1, bits(lfsr, 54, 1));
    t->io_acc_read_resp_ready = bits(lfsr, 6, 1);
    t->eval();
    t->clock = 1;
    t->eval();

    const auto& mr = t->io_mesh_resp;
    const auto& rr = t->io_acc_read_resp_bits;
    obs = t->io_mesh_a_ready;
    obs |= (uint64_t)t->io_mesh_b_ready << 1;
    obs |= (uint64_t)t->io_mesh_d_ready << 2;
    obs |= (uint64_t)t->io_mesh_req_ready << 3;
    obs |= (uint64_t)t->io_acc_write_ready << 4;
    obs |= (uint64_t)t->io_acc_read_req_ready << 5;
    obs |= (uint64_t)t->io_acc_read_resp_valid << 6;
    obs |= wget(mr, 519, 1) << 7;
    obs |= wget(mr, 518, 1) << 8;
    obs |= wget(mr, 0, 1) << 9;
    obs ^= wget(mr, 1, 5) << 10;
    obs |= wget(rr, 165, 1) << 13;
    obs |= wget(rr, 2, 3) << 14;
    obs |= wget(rr, 0, 2) << 17;
    obs ^= wget(rr, 133, 32) << 20;
    for (int k = 0; k < 8; ++k) obs ^= wget(mr, 6 + 64 * k, 63);
    for (int k = 0; k < 8; ++k) obs ^= wget(rr, 166 + 64 * k, 63);
    sum = ((sum << 1) + obs) & 0x7fffffffffffffffULL;
    lfsr ^= lfsr << 13;
    lfsr ^= lfsr >> 7;
    lfsr ^= lfsr << 17;
  }
  t->final();
  std::printf("gemmini16: cycles=%llu sum=%llu\n", (unsigned long long)cycles, (unsigned long long)sum);
  delete t;
  return 0;
}
